// RBE (Report By Exception) filtering
// Suppresses telemetry values that haven't changed beyond deadband threshold
// Input: msg.payload = {ts: <epoch_ms>, values: {key1: val1, ...}}
// Output: msg with only changed keys, or null if all suppressed

// --- AC #4: Critical/anomaly data bypass ---
if (msg.anomaly === true || msg.critical === true) {
    return msg;
}

var payload = msg.payload;
if (!payload || typeof payload !== 'object' || !payload.values || typeof payload.values !== 'object') {
    node.error('[rbe-filter] EvaluateError: unexpected payload format — missing values object', msg);
    return null;
}

var values = payload.values;
var keys = Object.keys(values);
if (keys.length === 0) {
    return null;
}

// Load deadband config from global context (set by config inject node on parent flow)
// NOTE: global context is required because subflow instances have isolated flow context
var thresholds = global.get('rbeThresholds') || {};
var defaultDeadband = global.get('rbeDefaultDeadband') || 0;

// Load last-sent values from node context (per-instance state)
var lastSent = context.get('rbeLastSent') || {};

var passed = {};
var suppressedCount = 0;

for (var i = 0; i < keys.length; i++) {
    var key = keys[i];
    var currentVal = values[key];

    // AC #4: bypass keys containing 'alert' or 'anomaly'
    if (key.indexOf('alert') >= 0 || key.indexOf('anomaly') >= 0) {
        passed[key] = currentVal;
        lastSent[key] = currentVal;
        continue;
    }

    // Non-numeric values always pass through (booleans, strings)
    if (typeof currentVal !== 'number') {
        passed[key] = currentVal;
        lastSent[key] = currentVal;
        continue;
    }

    var deadband = (thresholds[key] !== undefined) ? thresholds[key] : defaultDeadband;

    // AC #5: First message after restart — no last-sent value
    if (lastSent[key] === undefined || lastSent[key] === null) {
        passed[key] = currentVal;
        lastSent[key] = currentVal;
        continue;
    }

    // AC #2 & #3: Compare absolute change against deadband
    var change = Math.abs(currentVal - lastSent[key]);
    if (change > deadband) {
        // AC #2: exceeds deadband — pass through
        passed[key] = currentVal;
        lastSent[key] = currentVal;
    } else {
        // AC #3: within deadband — suppress
        suppressedCount++;
    }
}

// Save last-sent values back to node context
context.set('rbeLastSent', lastSent);

// AC #6: Track filtered count in global context (readable by stats publisher on parent flow)
if (suppressedCount > 0) {
    var currentCount = global.get('rbeFilteredCount') || 0;
    global.set('rbeFilteredCount', currentCount + suppressedCount);
}

// AC #2/#3: Build output
var passedKeys = Object.keys(passed);
if (passedKeys.length === 0) {
    // All keys suppressed — suppress entire message
    return null;
}

// Some keys passed — output with only passed keys
msg.payload = {
    ts: payload.ts,
    values: passed
};

return msg;
